    public Object parseMarket(Object market)
    {
        Object id = this.safeString(market, "symbol");
        Object id2 = this.safeString(market, "crossSymbolName");
        Object quoteId = this.safeString(market, "l2PairId");
        Object baseId = this.safeString(market, "baseTokenId");
        Object quote = this.safeString(market, "settleAssetId");
        Object base = this.safeCurrencyCode(baseId);
        Object settleId = this.safeString(market, "settleAssetId");
        Object settle = this.safeCurrencyCode(settleId);
        Object symbol = Helpers.add(Helpers.add(Helpers.add(Helpers.add(baseId, "/"), quote), ":"), settle);
        Object expiry = 0;
        Object takerFee = this.parseNumber("0.0002");
        Object makerFee = this.parseNumber("0.0005");
        final Object finalBaseId = baseId;
        final Object finalExpiry = expiry;
        return this.safeMarketStructure(new java.util.HashMap<String, Object>() {{
            put( "id", id );
            put( "id2", id2 );
            put( "symbol", symbol );
            put( "base", base );
            put( "quote", quote );
            put( "settle", settle );
            put( "baseId", finalBaseId );
            put( "quoteId", quoteId );
            put( "settleId", settleId );
            put( "type", "swap" );
            put( "spot", false );
            put( "margin", null );
            put( "swap", true );
            put( "future", false );
            put( "option", false );
            put( "active", Apex.this.safeBool(market, "enableTrade") );
            put( "contract", true );
            put( "linear", true );
            put( "inverse", false );
            put( "taker", takerFee );
            put( "maker", makerFee );
            put( "contractSize", Apex.this.safeNumber(market, "minOrderSize") );
            put( "expiry", ((Helpers.isTrue((Helpers.isEqual(finalExpiry, 0))))) ? null : finalExpiry );
            put( "expiryDatetime", ((Helpers.isTrue((Helpers.isEqual(finalExpiry, 0))))) ? null : Apex.this.iso8601(finalExpiry) );
            put( "strike", null );
            put( "optionType", null );
            put( "precision", new java.util.HashMap<String, Object>() {{
                put( "amount", Apex.this.safeNumber(market, "stepSize") );
                put( "price", Apex.this.safeNumber(market, "tickSize") );
            }} );
            put( "limits", new java.util.HashMap<String, Object>() {{
                put( "leverage", new java.util.HashMap<String, Object>() {{
                    put( "min", Apex.this.safeNumber(market, "displayMinLeverage") );
                    put( "max", Apex.this.safeNumber(market, "displayMaxLeverage") );
                }} );
                put( "amount", new java.util.HashMap<String, Object>() {{
                    put( "min", Apex.this.safeNumber(market, "minOrderSize") );
                    put( "max", Apex.this.safeNumber(market, "maxOrderSize") );
                }} );
                put( "price", new java.util.HashMap<String, Object>() {{
                    put( "min", null );
                    put( "max", null );
                }} );
                put( "cost", new java.util.HashMap<String, Object>() {{
                    put( "min", null );
                    put( "max", null );
                }} );
            }} );
            put( "created", null );
            put( "info", market );
        }});
    }

    public Object parseTicker(Object ticker, Object... optionalArgs)
    {
        //
        // {
        //     "symbol": "BTCUSDT",
        //     "price24hPcnt": "0.450141",
        //     "lastPrice": "43511.50",
        //     "highPrice24h": "43513.50",
        //     "lowPrice24h": "29996.00",
        //     "markPrice": "43513.50",
        //     "indexPrice": "40828.94",
        //     "openInterest": "2036854775808",
        //     "turnover24h": "5626085.23749999",
        //     "volume24h": "169.317",
        //     "fundingRate": "0",
        //     "predictedFundingRate": "0",
        //     "nextFundingTime": "10:00:00",
        //     "tradeCount": 100
        // }
        //
        Object market = Helpers.getArg(optionalArgs, 0, null);
        Object timestamp = this.milliseconds();
        Object marketId = this.safeString(ticker, "symbol");
        market = this.safeMarket(marketId, market);
        Object symbol = this.safeSymbol(marketId, market);
        Object last = this.safeString(ticker, "lastPrice");
        Object percentage = this.safeString(ticker, "price24hPcnt");
        Object quoteVolume = this.safeString(ticker, "turnover24h");
        Object baseVolume = this.safeString(ticker, "volume24h");
        Object high = this.safeString(ticker, "highPrice24h");
        Object low = this.safeString(ticker, "lowPrice24h");
        return this.safeTicker(new java.util.HashMap<String, Object>() {{
            put( "symbol", symbol );
            put( "timestamp", timestamp );
            put( "datetime", Apex.this.iso8601(timestamp) );
            put( "high", high );
            put( "low", low );
            put( "bid", null );
            put( "bidVolume", null );
            put( "ask", null );
            put( "askVolume", null );
            put( "vwap", null );
            put( "open", null );
            put( "close", last );
            put( "last", last );
            put( "previousClose", null );
            put( "change", null );
            put( "percentage", percentage );
            put( "average", null );
            put( "baseVolume", baseVolume );
            put( "quoteVolume", quoteVolume );
            put( "markPrice", Apex.this.safeString(ticker, "markPrice") );
            put( "indexPrice", Apex.this.safeString(ticker, "indexPrice") );
            put( "info", ticker );
        }}, market);
    }

    /**
     * @method
     * @name apex#fetchTicker
     * @description fetches a price ticker, a statistical calculation with the information calculated over the past 24 hours for a specific market
     * @see https://api-docs.omni.apex.exchange/#publicapi-v3-for-omni-get-ticker-data-v3
     * @param {string} symbol unified symbol of the market to fetch the ticker for
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object} a [ticker structure]{@link https://docs.ccxt.com/?id=ticker-structure}
     */
    public java.util.concurrent.CompletableFuture<io.github.ccxt.types.Ticker> fetchTicker(Object symbol, Object... optionalArgs)
    {

        return java.util.concurrent.CompletableFuture.supplyAsync(() -> {

            Object parameters = Helpers.getArg(optionalArgs, 0, new java.util.HashMap<String, Object>() {{}});
            if (Helpers.isTrue(Helpers.isEqual(this.markets, null)))
            {
                (this.loadMarkets()).join();
            }
            Object market = this.market(symbol);
            Object request = new java.util.HashMap<String, Object>() {{
                put( "symbol", Apex.this.safeString(market, "id2") );
            }};
            Object response = (this.publicGetV3Ticker(this.extend(request, parameters))).join();
            Object tickers = this.safeList(response, "data", new java.util.ArrayList<Object>(java.util.Arrays.asList()));
            Object rawTicker = this.safeDict(tickers, 0, new java.util.HashMap<String, Object>() {{}});
            return this.parseTicker(rawTicker, market);
        }).thenApply(io.github.ccxt.TypedCores::toTicker);

    }

